package africa.growtogether.platform.eiam.mfa;
import java.nio.ByteBuffer; import java.security.SecureRandom; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.time.Instant; import org.springframework.stereotype.Service;
@Service public class TotpService {private static final char[] ALPHABET="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567".toCharArray(); private final SecureRandom random=new SecureRandom(); private final MfaProperties props; public TotpService(MfaProperties props){this.props=props;}
 public String generateSecret(){byte[] b=new byte[20];random.nextBytes(b);return encodeBase32(b);} public boolean verify(String secret,String code,Instant now){if(code==null||!code.matches("\\d{6}"))return false;long step=now.getEpochSecond()/30;for(int i=-props.totpWindow();i<=props.totpWindow();i++)if(generate(secret,step+i).equals(code))return true;return false;}
 String generate(String secret,long step){try{byte[] key=decodeBase32(secret);Mac mac=Mac.getInstance("HmacSHA1");mac.init(new SecretKeySpec(key,"HmacSHA1"));byte[] h=mac.doFinal(ByteBuffer.allocate(8).putLong(step).array());int o=h[h.length-1]&15;int n=((h[o]&127)<<24)|((h[o+1]&255)<<16)|((h[o+2]&255)<<8)|(h[o+3]&255);return String.format("%06d",n%1_000_000);}catch(Exception e){throw new IllegalStateException(e);}}
 private String encodeBase32(byte[] data){StringBuilder s=new StringBuilder();int buffer=0,bits=0;for(byte x:data){buffer=(buffer<<8)|(x&255);bits+=8;while(bits>=5){s.append(ALPHABET[(buffer>>(bits-5))&31]);bits-=5;}}if(bits>0)s.append(ALPHABET[(buffer<<(5-bits))&31]);return s.toString();}
 private byte[] decodeBase32(String s){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int buffer=0,bits=0;for(char c:s.toUpperCase().toCharArray()){int v="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567".indexOf(c);if(v<0)continue;buffer=(buffer<<5)|v;bits+=5;if(bits>=8){out.write((buffer>>(bits-8))&255);bits-=8;}}return out.toByteArray();}
}
